insert into negocios (id, nombre, slug, categoria_oficial_id, municipio, vereda_id, direccion, latitud, longitud, descripcion_corta, descripcion, producto, telefono, whatsapp, email, representante_legal, nit, naturaleza_juridica, delegado, tiempo_constitucion, rut_camara_comercio, responsable_cdmb, novedad, tipo_negocio_verde, codigo_marca, anio_registro, cota_msnm, este, norte, aplicacion_ficha_2025, observaciones, registro_nacional_turismo, uso_suelo, concesion_aguas, concesion_aguas_vencimiento, vertimientos, vertimientos_vencimiento, pueaa, pgris, pozo_septico, alcantarillado, ica, ica_vencimiento, invima, invima_vencimiento, certificado_tenencia_animales, buenas_practicas_agricolas, buenas_practicas_apicolas, registro_apicola, intervencion_cauce, capacidad_carga, sstt, canal_venta, exportacion, huella_carbono, fortalecimiento_tecnico, fortalecimiento_academico, fortalecimiento_financiero, internacionalizacion, certificaciones, posicionamiento_marca, beneficios_ventanilla, fortalezas_ambiental, fortalezas_social, fortalezas_economico, debilidades_ambiental, debilidades_social, debilidades_financiera, emprendimiento_verde, sello_marca, avalado, destacado, activo) values ('a6e5bc35-304e-48dc-a73f-d36e0bac8d00', 'COCOA KING', generar_slug_unico('COCOA KING', 'a6e5bc35-304e-48dc-a73f-d36e0bac8d00'), (select id from categorias_oficiales where slug = 'bioproductos-servicios-sostenibles'), 'Bucaramanga', (select id from veredas where municipio = 'Bucaramanga' and slug = 'san-pedro-bajo'), 'VEREDA SAN PEDRO FINCA MI CABAÑA', null, -73.12235472222221, 'Cocoa King es una empresa familiar que se dedica  a la producción, transformación y comercialización de cacao de manera sostenible, aplicando buenas…', 'Cocoa King es una empresa familiar que se dedica  a la producción, transformación y comercialización de cacao de manera sostenible, aplicando buenas prácticas de cultivo donde no usa ningún tipo de agroquímicos, realizando el reciclaje de nutrientes del residuo del cacao (cacota) y la gallinaza para ser usado como materia orgánica en el suelo. La transformación del grano de cacao en chocolate de mesa artesanal la realiza en sus propias instalaciones. Los productos son elaborados sin ningún preservante lo que le otorga una calidad única y natural a sus productos, que comercializa en tiendas saludables de Bucaramanga, AMA CAFE con las cuales se tienen acuerdos verbales de comercialización de los productos; de igual forma, realizan entregas al público en conjuntos cerrados en Bucaramanga y su área metropolitana, usando como medio de promoción sus redes sociales (Instagram, y WhatsApp) y por medio del voz a voz. La empresa realiza acciones como la conservación de la biodiversidad mediante el manejo del cultivo de cacao en modelo agroforestal con el asocio de árboles maderables de sombrío y plátano, realiza prácticas de conservación del suelo dejando de lado el uso de agroquímicos, aplicando materia orgánica y realizando el reciclaje de nutrientes con la reincorporación de la cacota del cacao, las podas del cultivo y la gallinaza de los animales para elaborar abono orgánico que aplica en el cultivo, se hace preservación rondas hídricas dejando áreas de conservación. De igual forma, utiliza para el empaque de sus productos materiales biodegradables. Así mismo, realiza el aprovechamiento de productos y residuos vegetales de la finca (cacota de cacao, plátano, yuca, bore)', 'CHOCOLATE DE MESA', '3157308159', '573157308159', 'mariaca9610@gmail.com', 'JOAQUIN CONTRERAS MENDOZA', '91219330-9', 'Natural', null, '43 MESES', 'Camara de comercio', 'NATALY RAMIREZ', 'ACTIVO', 'Dinamizadoras', null, 2021, '1.112 msnm', '73°7''20.477''''', '7°12''31872''''', 'ACTUALIZO', null, null, 'SI', 'ACUEDUCTO VEREDAL', null, null, null, 'NO', 'NO', 'SI', null, null, null, 'SI', '2035-09-12', null, 'NO', null, null, null, null, 'NO', 'B2C', 'NO', 'NO', 'Comercial y administrativo', 'MARKETING VERDE Y COMUNICACIÓN AMBIENTAL', 'Potencializar producción y saldar deudas', 'ASESORIA Y CONOCMIENTO PERO QUIEREN EXPORTAR', 'INVIMA', 'Requiere posicionamiento de marca', 'HA ASISTIDO A FERIAS DE NEGOCIOS VERDES Y ACOMPAÑAMIENTO POR PARTE DEL ASESOR, ESTE AÑO OBTUVO EL INVIMA', 'Cultivan su propio cacao orgánico, sin uso de agroquímicos.
